/**
 * Starts the EXPRESS-011 app on a real port so you can send requests by hand.
 * Run: npm run dev:express:11   (restarts on every save, which also resets the notes)
 * Do not edit this file; write your solution in task11.ts.
 */
import type { NextFunction, Request, Response } from "express";
import { createApp, type Note } from "./task11";

const PORT = Number(process.env.PORT ?? 3000);

const sampleNotes: Note[] = [];

const app = createApp(sampleNotes);

// Runs only for errors your code does not handle itself: prints the full error
// in this terminal and returns it in the response, so a 500 shows what broke.
app.use((err: unknown, req: Request, res: Response, _next: NextFunction) => {
  console.error(`\n500 on ${req.method} ${req.originalUrl}\n`, err);
  const message = err instanceof Error ? err.message : String(err);
  res.status(500).json({ unhandledError: message });
});

app.listen(PORT, () => {
  console.log(`EXPRESS-011 running on http://localhost:${PORT} with no notes`);
  console.log("Tokens: token-alice, token-bob, token-root (admin)");
  console.log("Send requests from src/express/task11/requests.http");
});
